) AS (
  VALUES 
    (547::BIGINT, 'Increíble profesor, a veces se desvía y explica de más y medio lo confunde a uno, pero no dudaría en volver a llevar con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '9347c96b35addc17bd9000df2c6a170ca8c5d139049e555697d47d41a73d616e'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, 'Es desordenado al explicar, pero explica bien y es súper buena nota. Califica bien, cómico, suave, quizzes sencillos,'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'cde708ac7215caf159c04b220be0c7dbcaf6c88e696036673e02c59f26e4c06c'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor y humano, sus clases son muy cómodas, se le entiende con mucha claridad. A pesar de ser un curso un poco pesado no se siente con este profesor, los exámenes son fáciles y sus quiz igual, es flexible mientras haya responsabilidad de la parte del estudiante, es la mejor opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-08T00:00:00+00:00'::TIMESTAMPTZ, '50a99c55b2f4d3f9a423fc4b96c00b50647be597ea67e29a214eb7b3a997b0ec'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor, es alguien quién hace interesante e inspira llevar química, recomiendo totalmente llevarlo con el, explica increíble, compara lo teórico con lo práctico muy bien y encima brinda apoyo y hace la clase dinámica.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-10-02T00:00:00+00:00'::TIMESTAMPTZ, '2238e5ee72c05645e99ff54cc933b1a3865dea1a630f7e4a27a84e62c2e5cb3d'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor profe de química, es cierto q lo único malo puede ser q hace preferencia con los mas aplicados, pero como profe da muchos quices extra q eliminan los bajos y en clases da 1 hora la cual es rápida y concisa básicamente va al grano, con mínimo esfuerzo se pasa el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'dbf4ea2f8c00fdce53a6b042b94d0cb7f309a4edab93b07e8de1fd1d80f11bdb'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Isaac hace las clases súper claras y cortas, califica en los quizes lo que enseña y si no queda claro lo explica de nuevo. Le gusta la participación y preguntar, pero lo recomiendo bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'da515b3f05224445233846166f63939b4c9d19a6b7ce4e3f1ad8fbd621c5356c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es un excelente profe, las clases son de máximo 1 hora y explica lo necesario. Es muy buena gente y hace más quizes de los requeridos y al final pone las mejores notas. Con ir a todas las clases y estudiar del material de la catedra le va a ir bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a1bae2ac9aedc4d6afd72cc9c8ae828ce61c38a8521b39452259920308f596ab'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe sabe demasiado y explica muy bien, se nota que le apasiona la química y hace que uno realmente se interese por el curso. Los quices si son duros, pero llevando la materia al día es suficiente. A veces hace comentarios un poco pesados, pero uno se acostumbre, intente caerle bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2334349345ea88c5dc139f2a5987b96809a8ccdf3f9885210bbcb57a2bf6b722'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Muy buen profe, le gusta mucho la química. A la hora de calificar se pone rudo pero cuando llega la entrega final es buena nota. Recomiendo llevarlo con él.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3914f892fe65c431c8b9fabd6c186daa6adcd83311b230f19b7db5fe47e8897f'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor, se nota que le apasiona la química y explica muy muy bien. Las clases son cortas y 0 pesadas. Los quices son difíciles pero si estudia (con la cátedra, ojalá) le va a ir bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, '8188024dc0d826bbfba0a9aea443a78e3db064262c4c4d818ca7318f55d07760'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'De los mejores profes, una clase corta pero super útil. Me gustó mucho cómo dio el curso y apoya bastante. Eso sí, tampoco regala nada además es de los más preparados'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'ddcabab20a936531461be60b06bafc82b1202eb44e4c4d9f52f50e36584048d5'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profesor es realmente bueno en química sin embargo sus clases son confusas ya que no utiliza presentaciones ni material de apoyo y suelen durar 1 h, califica muy duro y tiende a tener preferencias con los estudiantes que dominan mejor la materia, también puede llegar a decir comentarios groseros'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '2adc0366d004d719b083fe9f69df1892fd497c3f8bb6a1e73011d2579642ffdb'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Él como profesor es realmente bueno, como persona no tanto, lo que hace que si vos no sos de sus preferidos te va a tratar mal y no te va a querer ayudar ; las clases duran 1hr o menos y si hay que estudiar para los quicces...'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2023-12-14T00:00:00+00:00'::TIMESTAMPTZ, '82b76b2c3ce3c3dcd99ba574766f51ccac68c576384c1aad6a3f3401dc3f6ff1'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente persona, hace sus clases muy divertidas y amenas. Da solamente una hora de clases, y hace quices casi cada semana, no son difíciles pero sí hay que estudiar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, '82c9796da043c3b6e6f12cdb5e8f84a524df64d1e69aa7853647ad20d664d53f'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe da la clase de forma clara y concisa, dura solo una hora en clase porque va al grano pero si uno le presta atención de verdad comprende todos los temas. Da muy buena retroalimentación y lo prepara a uno con preguntas del examen, da muchas oportunidades para reponer quices. Recomendadísimo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '7b10b4263133a55922022038925d4b3ac7dd18637c11309f7e1b1164a382a068'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe, las clases son cortitas y van directo al grano, explicaciones super claras y es bastante ameno. Uno de los mejores profes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'b4d01ee68f323eafc8f7f57727131eddc60775cfe0d4a70e1c9f1f3c9e6f5c3c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Uno de los mejores profes que tiene el Tec, sus clases son entretenidas, se siente buena vibra en clase, además de ser buen profesor es buena persona con los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a47fde8aab570fc99f3d661e93b17c4607b4e3c1f0fba609e0f915c78cffe510'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor, explica muy bien. Los quices son complejos, pero si se estudia la materia tampoco son muy complicados.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'e34875258f62b94171722a8d6e5dab4957548c2fd4dc4bc8ebbdce9353b7c63e'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'El curso es rudo pero con el profe se disfruta mucho la materia. Super tuanis como aprende uno y la forma en que enseña. Los quices son difíciles y hay que tener la materia al día sobretodo porque hay examen final'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '730d8bd98946710b8d95b9e83e07c3c5ce30974f2c23af172e113db875786c00'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Simplemente el profesor más tuanis que hay. Como persona es sumamente interesante y como profesor no tiene igual: Las clases son cortas y no se sienten pesadas(50min-1h en promedio), Explica bien y ayuda con las dudas sin problemas. Un poco de cuidado con el exceso de confianza nada más.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6009ea6ddc641eb3a3d3765517594528a9f1b372dcda86b1fc9ad43be91cbae2'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor, se nota que le apasiona la química. Explica súper claro y se preocupa por uno. Los quices son bastante rudos, estudie antes siempre porque tienen mucho valor. Muestre interés por mejorar siempre, eso le va a ayudar al final del semestre si le falta algún punto.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '73d54aa4e9280bc299c1705bd4b75766094f0d0da3ef956ba253a10d0d15291f'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Me parece un gran profe, se esfuerza para que todos en la clase entiendan, explica bien y responde las dudas por Teams bastante rápido. Los quices no son tan fáciles así que de fijo hay que prepararse, suelen haber quices extra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, '91e43578c55bf14278fe2c9d6b02aae3a55ffafdc85202a25d05ce1f66aeff3e'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Muy buen profe. Explica muy bien e intenta que la materia se entienda. Los exámenes no son los más fáciles pero tampoco son imposibles. Yo lo recomiendo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, '5597814ada0b31564dc268cea1d0930bbb8fffb0ae0c2304727ccf1fd8cc84f5'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'El profesor es un acosador sexual!!!!! Fue suspendido en el momento que me dio lecciones diciendo que fue por motivos administrativos cuando fue que lo suspendieron por acoso sexual :) no lo recomiendo para nada, hace comentarios pasados e incómodos a estudiantes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'b1ca62f0f9ab81c66138131db7ffa5effe180ee5b6eb77ea3998c6307deb4dbe'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Es excelente profe, comprensivo, empático, a veces algo sarcástico, pero sin intención de ser grosero. Los quices si requieren mucha preparación, pero el profe explica super bien e incluso hasta más, hace la clase entretenida y de verdad se aprende, muy claro con las evaluciones. Matricule sin dudar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '15024c8460c7a71539767c8375ea9b04253feee2d3240f3e9c476efa5b4e119f'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '0d3a811b7e3b948e89779ee1d7ffd8c0a7a0b86222d4d7ba5996c8fb123c77f5'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El peor profe, borra los comentarios malos de acá. En el curso no se le entendía nada y no brindaba apoyo. Ni siquiera dejaba claro cual era el libro del curso...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-05-06T00:00:00+00:00'::TIMESTAMPTZ, '18ea67ab3302ec00a259ced2076ece626847866019e9186932fc2a6602db8322'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Es increible tanto como profesor a como persona, no por nada es el coordinador de la cátedra, sabe demasiado y explica super bien. Si bien el curso como tal es un poco complicado, él hace que uno entienda mucho la materia a pesar de que sus clases son super cortas, definitivamente lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-04-06T00:00:00+00:00'::TIMESTAMPTZ, '6a2b636b1b784c5f018656b1ce2e3af93ff9fc7eff37e14aa4ea7aa69f7f81fa'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor profesor que he tenido. Explica excelente. Ayuda a sus estudiantes. Recomiendo mucho asistir siempre a las clases porque los quices que deja son duros pero siempre busque entender todo porque él no deja de explicar hasta que sepa que todos entendieron :)'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '9a9d48b7f5fa348ca0c2cccd29cb8bdb696484a82dc9b3cb3de44a92ef2a6bd2'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'De los mejores profesores del TEC, si matricula con el, tenga seguro que pasa los exámenes parciales, los quices son duros pero se logra el es un excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a954b83cc6d95eb406727dd80b5ad83d95ad488fc449f8b17e3cf9c56b963515'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es muy buen profe, a veces puede ser un poco grosero si le preguntan cosas obvias pero en general 10/10. Para los quices hay que estudiar por que si tienen cierto grado de dificultad. Con él los parciales se pasan fácil-'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c850637646debb7da054ca4bf5cc6cae09a14558ecaa8bf56a695340e3f96ed5'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un profe que se nota que le gusta lo que hace, ayuda a los estudiantes y hace unas clases cortas pero muy útiles. Sus quices no son los más fáciles, pero puedes estar seguro que aprenderás. Si quieren pasar fácil y NO aprender el prof Isaac no es la opción.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-09T00:00:00+00:00'::TIMESTAMPTZ, 'a0b7b276ae6c584506814f7f19dfd13a554b46b2d0a80e67262c008c7e943021'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es demasiado grosero cuando usted tiene dudas en clase, suele responder con "es lo que acabo de decir" "ya lo dije 5 veces" "de eso se ha tratado toda la clase de hoy" mejor averigue por si mismo, lo quices suelen ser algo duros, pero si algo se rescata, es que si se aprende (a huevo)'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'a46626798415ada979eb7e2b3af86c949bbe565c295dd2980079bf890e219604'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe sabe mucho y como persona no es tan mal, pero califica rudisimo y espera que uno solo se enfoque en el curse de él. Es demasiado grosero a la hora de calificar y si se pregunta algo en clase depende responde super odioso, hace quizes cada semana y son demasiado dificiles'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'bbe673baea940b44f85b9e759c7f684697a9d751e772e137a61c68f010844769'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Es muy bueno, da clases de 1 hora donde se entiende muy bien, los quices son faciles y sale lo que se ve en la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '03bd24754c26277b85993e438c912c6e597a963b9f9eba68e80ca7286750d97b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe explica muy bien, sus quices son algo duros pero si se estudia y se esfuerza no es tan difícil pasar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '7e8236fb99496129f4ab585c53cff5db57b130609f13a45aabe481ac0c9c6ade'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Los quices son rudos pero después de ahí todo normal, es por medio de la cátedra y él te da buena retroalimentación. Si quieres pasar el curso fácilmente, ÉL NO es la opción. Si quieres APRENDER, sí.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3138d9bc2fdec8c42a66c3fed4104c0fff2c4f3f4fa89a4f690dda3bfbd94bf0'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No lo recomiendo, es un poco grosero y pruebas cortas super difíciles, es buena gente fuera de clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '21ac8cd2c98f87a5880a930d1e730bee0152233c48dd423f92cab10d39e21498'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'El profe explica muy bien y aclara dudas en clase, solo tenga en cuenta que hace quiz muy duros, tiene que ponerle bastante ya que hay quiz todas las semanas y hacer bien los proyectos para pasar, y si usted le pregunta algo que el mencionó en clases le responde de manera odiosa, sería lo único malo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5d7bd588677db77704d641ad4360a61523d048f1e6a7909553c14da86588fd5a'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Se aprende demasiado y se involucra mucho en el aprendizaje. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b1f8be05acb9027f3b14ba69eb1366141d178a63d66df0815cb00c20d7898b7f'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Es un muy buen profe, explica bien pero sí califica duro en los exámenes/quices. Deja proyectos que pueden ayudarle a uno mejorar la nota. De vez en cuando da puntos extra pero si pone atención en clase o hace bien los ejercicios de puntos extra.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-06-20T00:00:00+00:00'::TIMESTAMPTZ, '99edafd6f435b36f2d1971410cfca9cca38f23741f8450cc059d40c8b1e41f29'::TEXT, ARRAY[1434]::BIGINT[]),
    (547::BIGINT, 'Súper buen profe, se interesa porque lxs estudiantes aprendan, lo mejor de todo las clases son de 1 h aprox y en ese tiempo explica lo que debe y de forma muy clara con ejemplos. Es cierto, los quiz son difíciles pero él explica muy muy bien, tons no le tenga miedo al éxito meta con él, éxitos…'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'f6b231e1d3707e1e41eff3a72a78398c9823d1172b1fb2b3f0119cce4d8c3d1d'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un profesor excelente, hace las clases de aproximadamente una hora, pero a esa hora se le saca mucho provecho, con asistir a las clases y realizar los quizes (que tienen una dificultad moderada) la materia se pasa easy'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '02103f3a4c8736f06c6323108da57db53f9e3ab0cd8ad5454b101b3fe1a11197'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profesor explica super bien, es muy conciso con los puntos a tratar de la materia, su clase es muy divertida por lo que es más fácil poner atención. Pone ejemplos de la vida cotidiana por lo que entender lo que explica es mucho más sencillo. Pero sus quices son algo duros jaja'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, '21a483d505ca379282c75f6e48daeff5911f16ae1ae30578fab5d23b0c974bdc'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'En general es de los mejores profes que he tenido en MI VIDA. Sabe mucho, hace las clases cortas y prepara bien para el examen mediante quices de dificultad considerable. Con ponerle atención a lo que dice ya pasa el curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Inspirador']::TEXT[], '2021-04-17T00:00:00+00:00'::TIMESTAMPTZ, '653f9d83cfd23c2e00885e6839a383a87325258c24bd0707f2cae52db6ef8863'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '9ca50e9f53258b0f50cdef453d69635040a230755d58e911fd6fcffb9848d14a'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe sabe demasiado y si a usted le gusta la ciencia entonces las clases le van a parecer muy inspiradoras. Hace quices semanales bastante duros pero que preparan bien para el examen'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '410f18b5d9a1bfef0ac2a3951d8f1931263f65e2466ea0f23c6eeab8c6036497'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe de Química, se preocupa por la salud mental de los estudiantes, es muy atento, sus quices semanales son duros pero lo preparan para el examen. Dele sin mieo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'a09bb66d13a22b7e7bcd2c3b974be98064c8469c937f475ca45ff3c0d8e8bcf3'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Los quices tienen cierto grado de dificultad. Las clases son buenas, explica para el examen. Genera un ambiente de mucha confianza, casi que excesivo, por lo que uno se siente incómodo. Pero fuera de ese detalle lo recomiendo como profesor.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '1d3462f6440116814f814d257a75eacc9d46c57c34c53c9617f82adc339b63c6'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Los quices son duros, hay que estudiar. Las clases son excelentes, explica muy muy bien y prepara para el examen. Lo recomiendo mucho , solo que a veces es un tanto grosero'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'aa67e0eeee92c577ae0bdaccd11b5fe94e1967f42104b0746cc683b768690609'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es super claro, las clases son para aprender de verdad. Los quices son dificiles, sin embargo eso le ayuda a uno para prepararse para los examenes. Ayuda a entender la materia en caso que uno no entienda. Es un profesor tuanis y hace amena a la clase. LO RECOMIENDO.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b802026ff11184bcb5777823329a4678438fa8543ce1a0f3d22be72f00469da2'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Muy buen profesor, de lo mejor de la escuela, califica un toque duro, estudie para los quices'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'b527df6e8fadeda24f5eb9f45cb79dff5640ffe3b6dcb6e4021faa3b9c9f4e4d'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Se recomienda bastante, a veces le da por pasarse de confianza con los estudiantes y llega a ser un toque incomodo, pero es un buen mae y gran profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ead575f0493d6a0d4c67ca4785a0a34f6d68ac1fbbcc7f5de037321400bcb5da'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Hace chistes un poco raros y pasadillos pero como profesor es excelente.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1439a6263272d2a2d07b73d9bf6049b4a687a4fd6198bff4afe255078e823b92'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Gran profesor y persona Super recomendando en virtualidad, sube clases a YT y demasiado anuente a dudas de estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-12-12T00:00:00+00:00'::TIMESTAMPTZ, '1362f063aaecc473f2b19d80eb9738ca69e3b32006c926086303e00da0b00d5c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor para esta materia, se aprende, prepara bien para los exámenes, siga sus consejos, de verdad Química II se pasa bien si lo llevas con este profesor. Una teja de persona y de profesor, el mae de verdad que sabe, está super preparado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'dfdafd6c090cbfdab70e3c887e95d02c5032dc3d4dc91cc05a09786c5059eb90'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Junto a Roldan, de los mejores profes de la catedra. Tienen demasiado conocimiento, siempre ayuda y es pura vida. Los quices son duros pero eso lo prepara mejor a uno para los exámenes'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-06T00:00:00+00:00'::TIMESTAMPTZ, '6d82e14d0106e8b5625b799dfe6e8259af9b157f8f8ca8cfe4cb60aa398b2801'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'De los mejores profes qué hay. Es súper preparado, pura vida y le importa que uno aprenda. En negativos, califica duro ya que espera siempre lo mejor de los estudiantes y hace quices bastante rudillos (estudie). Esfuércese mucho desde el inicio y a final de semestre me lo va a agradecer ;)'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'b953f9a18868f2d48a69c47cc0a4c20cd36f98eb4eb4c388a2377c6d282363b7'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es un crack, se interesa porque uno aprenda, los quizes son rudos, pero se pueden en parejas, califica justo y es un 100 de persona. El mejor profe que he tenido hasta el momento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '536bb8a49e0fb8b568b694f45e4930a541b6e8a6c943ee88889457288bda749c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Hay que estudiar para los quices porque si los hace un poco dificiles, es excelente profesor, sus clases son super divertidadas, se aprende demasiado y es suuuuper buena gente. 100% recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '01534afc457123d352d6545a7ccbdd9501711a7691452c541def72177b4201ce'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe. Cinco estrellas. ?????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '873a59bc649df777022ee64210f8bca36c4658946c63b13cf426107c3c0c1d2b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Fantástico profesor, hay que estudiar para los quices porque son dificilillos. Se preocupa un montón por un y de verdad se aprende DEMASIADO con él. 100% recomendado llevar el curso con él, las clases son de las más divertidas y disfrutables.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '2b4169c832f4925ead0db6a6f3cb04245c6c98ad3be14202cb8f6da519f37865'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es el mejor profe, se preocupa mucho por el estudiante y trata de crear un ambiente de confianza. Es súper inteligente y trata de transmitir mucho su conocimiento. Explica muy diferente a otros profes, lo que hace que uno entienda mejor la materia y le sea más fácil. Matriculé con él, no lo dude.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'b01325ed23119857115d2a3765d0f7cc21c09598ce214b750d6ed44a09dbe9a0'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Explica super bien, es muy organizado. Los quizces son bastante rudillos y no hace mucha práctica pero en general es un muy buen profe, recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-13T00:00:00+00:00'::TIMESTAMPTZ, '573d71ffff25136009f345a2ff042f7f6d13350e91b3dd3d9cb855fd6b044e19'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un excelente profe, los quices son durillos hay que estudiar, pero cuando llegue el parcial ya va a tener todo bastante repasado, y se lo va a agradecer al final de cuentas. Además es super tuanis'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '0fb266b9849dd1bc4ff75f2f9d8cc339a0a3ab48c781a9b3bd254ae71afe0f14'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor profesor que he tenido en mi vida. Sus clases son divertidas y claras, explica varias veces si los estudiantes no entienden. Hace evaluaciones extra que ayudan con la nota. Amable, divertido y sarcástico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2019-07-15T00:00:00+00:00'::TIMESTAMPTZ, '7439bf7df5be8490d3b7fe11a4448e117e205555b49603f26d43ec5eb45c666c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un excelente profesor, lástima que la escuela de química y ambiental tiene tan pocos profesores como él. Super recomendado. Puede que los exámenes sean duros, pero no son imposibles. Se preocupa por los estudiantes y porque la materia quede clara.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2019-06-27T00:00:00+00:00'::TIMESTAMPTZ, '917cdd4ea27cba6479a6a377e3022511fe8a375565575a8e9342e7b0bb825cb9'::TEXT, ARRAY[3175, 3174]::BIGINT[]),
    (547::BIGINT, 'De los mejores profesores que he tenido'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'cc656da881196121cbadab1d4c4be037249d1e0daec479494f101412459e0403'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Por su bien matricule con este profe, y ponga mucho interés en la clase los quices son un poco dificiles pero muy similares al examen, el da muchos puntos extras y se aseguro que usted entienda en la clase'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '314f1cb3762c1262045f4c16b31c14432b8ecc72c474c069aeac4035a9ef7102'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es súper buen profe. La clase no es aburrida. Le gusta la participación. Ayuda bastante en consulta. Es divertido y explica muy bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '610b0d4f685a27b4e1cfcc775c963ba64e7ffa174e25c0e9cce4ba01b0e17277'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'EL MEJOR PROFE! Estudie del cuaderno y los quices y fijo pasa.El profe es súper buena gente y además sabe mucho. Se preocupa por sus estudiantes y se disfrutan mucho las clases . NO DUDE EN MATRICULAR CON ÉL!'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'e1cd526284f1e1ae045d7b383c4dc11a9ad34e7c3134258ca0774c51c5297ccc'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'yo no lo recomiendo, clases muy mecanicas y aburridas y quices dificiles con poquisimo tiempo'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-04T00:00:00+00:00'::TIMESTAMPTZ, '68a94f40eccfbcb91dc2d05e81b6a8e9f81aadd2558a818b71b369950baf902a'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Isaac es un DIOS! Dele sin miedo, solo póngale a los quices y listo. Aparte quimica II es fácil y con él mucho mejor. Enserio, es un crack!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-05-24T00:00:00+00:00'::TIMESTAMPTZ, '13502c1359308c84cc09afa3fb9b6640132855ada884faed46fdbbea36008c0c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe es bueno, pero si lo va a llevar con él ponga mucha atención, los quices son duros y tienen un gran porcentaje en la nota, vaya a consulta porque no da practicas y todos los examenes están sin respuesta'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2019-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'eafc95199b042f3ed285cc38fe98d9162a98549f42bf031a51c629eee3a70cad'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Top 10 profes en la vida. Este mae cae súper bien y te hace la clase interesante. 12/10'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-27T00:00:00+00:00'::TIMESTAMPTZ, '23885a6817f528a7354e8c46409875a7df05f17bb77b44e187a1537dece2dd40'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor profe. Clases muy entretenidas, administra muy bien el tiempo pues logra ver todos los temas del curso y le enseña a uno sobre muchas otras cosas (al final dejó formulas matemáticas como quices extra). Me encantó llevar con él, hizo el curso muy fácil. Además es bastante comprensivo :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '56e6b6068b4a2c1dedeca467043331ce1f1be8b07d134708688bebb5be3404b7'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es el mejor profe del mundo, uno sólo estudia del cuaderno y fijo pasa, además es una excelente persona y clases muy entretenidas. Con él cualquiera aprende y le agarra gusto a la química'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b237c9d824cc6609cfc8c70d939d5dd7fb828b7f24459cc3abcd50f0954ca42d'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es el mejor profe, conoce demasiado y lo va a obligar a salirse de su zona de confort'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1f5a5bd9858bd109e9010a165ede76fee92310d0eee6a3324dc1522365ac23b4'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'EL MEJOR PROFE!!!!! Super buena gente, divertido, aprende uno un montón de cosas no solo química, explica super claro, definitivamente el mejor para llevar química 2. Vaya a todas las clases, estudie del cuaderno y le va a ir super bien. Estudie para los quices.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '821bdd772cba98d7d5a463813269abdc3426d3ebda21417bb184012392d5f100'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Explica súper claro la materia y las clases siempre son entretenidas. Estudié para los quices con los ejemplos que da en clase es más que suficiente, solo que da poco tiempo para hacerlos y son al inicio de la clase así que no llegue tarde!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2018-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c98712abb23694258ba2474a4fe0a3f13b40d5a295d601998ab18555c8016a53'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un curso difícil pero en el que se aprende muchísimo. Se disfruta con el Profe Isaac'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'db8fbd8e8841ac81982b4fde9c4ebd9bdd9d1ef45b06ef34a856d13464456435'::TEXT, ARRAY[949, 950, 2123, 948, 951]::BIGINT[]),
    (547::BIGINT, 'El mejor profe de química II, un gusto total ir a clases con él, aprendes de todo un poco. Y es de los poquitos profes que si salís mal en un examen, desde un inicio comienza a motivarte. Lo mejor de lo mejor. Re contra recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-30T00:00:00+00:00'::TIMESTAMPTZ, 'c7867a2375880d8498172903789aaf0fc3f42925f3ac8ba6f9cabf47734c849b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un excelente profesor, de verdad que disfrutas la materia y aprendes a algo más que química. Lo recomiendo mucho, no lo duden, con él van a aprender y a pasarla bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-10T00:00:00+00:00'::TIMESTAMPTZ, 'a572ef285b40ca0543c31267dd2496781e98e7b8351437021ce1510e258d2bc1'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'NO ENTIENDO LA CALIFICACION, es el mejor profesor fuera de mi carrera (electrónica) que alguna vez he tenido. Las personas que se quejan es porque no van a clases o no ponen de su parte para entender. Les aseguro que es el mejor de todos los de Quimica II , póngalo como su primera opcion'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'afab3526dc550b57454fdc720f19c694331f1b4342c0119f0ccb3bb5b2bc28e0'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe, se aprende mucho, y no sólo de Química...no lo duden'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-10-04T00:00:00+00:00'::TIMESTAMPTZ, '56eb3437b45b540b948a23233c26328491a2e5370035a026273a0dfeb6d2f999'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-09-07T00:00:00+00:00'::TIMESTAMPTZ, 'f071aaac7fd6a2ff4dd21e05109254d182f4d9354da136f95cc3a7098f6f2f35'::TEXT, ARRAY[3175, 3174]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2018-09-05T00:00:00+00:00'::TIMESTAMPTZ, '1b6a6af2a1c7f238f01fb0fcaf86065e80360ac5c942979bf51f9317b39b6404'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe Isaac es excelente, ayuda a quien lo merece, la clase nunca es aburrida y terminas aprendiendo mucho. LO RECOMIENDO. Los que lo evalúan mal seguro es porque perdieron el curso y no le pusieron.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes']::TEXT[], '2018-08-15T00:00:00+00:00'::TIMESTAMPTZ, '0b17bf39eaeb3bbfc3129a20622d308bdb6e184b6971be80b492b7931bce5970'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'sabe mucho, sin embargo no es el mejor para enseñar ya que se cree tan sabio que todo le parece tonto, no se para que se mete a dar clases si todo lo da por obvio. Pesimo, el 90% de la clase se la pasa conversando sobre el y 10% explica un ejercicio en 15min. Se me hace alguien prepotente'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico']::TEXT[], '2018-08-10T00:00:00+00:00'::TIMESTAMPTZ, '4ffaadb6d8ee5339f9d17c04b079d8fb75a823d101f8dd97867d6ef24bc00153'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '5033068b48daf543ec9862e566cd2dd40dfbf4f0c46409a9870ce98b73d2fa54'::TEXT, ARRAY[3175, 3174]::BIGINT[]),
    (547::BIGINT, 'Super buena nota, se nota el dominio y el amor por la química. Los quices son razonables, el que estudia los pasa sin problemas. Le gusta discutir sobre temas fuera de la materia, para hacer amenas las lecciones. Claro, conciso y conocedor, Una teja.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '19817565bee11ff14c92a5f474d33b7a2483d9cb610dff40a8a4102fb55b86c5'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Un excelente profe...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4c264349d3ec4187abacf3ed3f5b86c7322cf4f2424a1466009b9eb35338d52f'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Muy inspiracional. No lo dude y matricule con él, va a aprender mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '4a536651a02c0499d0213c0f651aec65379fe8d7d1522f098fad6613f99a0b17'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Buen profe, hace la clase muy entretenida, ayuda bastante, bastante recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'cd2ed0003d3ca9f1b3c1b157159f2187ad797e0b6b8df741d829231618b905ff'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Me ha encantado el curso con él. Se aprende mucho. Lo recomiendo al 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-09T00:00:00+00:00'::TIMESTAMPTZ, '0c19f14a71bc71866ed2343a87dc19d0c148c525f80e9deb2970ea4df02c36d4'::TEXT, ARRAY[949, 950, 2123, 948, 951]::BIGINT[]),
    (547::BIGINT, 'GENTE NO SÉ PORQUÉ LA CALIFICACIÓN TAN BAJA, es demasiado buen profe, de los mejores que he tenido, explica demasiado bien, de vez en cuando deja tareas pero ni obligatorias son, haces quices extra para ayudarlo con la nota, muy buena gente y la clase es cero aburrida, póngalo de primera opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '83fe8b07d8fdf828f3ad45ad496f97fc0a8586c661c36aed465420b62834a657'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No lo dude, la verdad la va a pasar muy bien y, sobre todo, va a aprender mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Inspirador']::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, '280943d6773e63b0197bfdfb2383785e778de8243c56567c57cc3a7a8668a6bb'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Aunque sabe mucho de la materia no es el mejor explicando, los quices son bastante rudos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '04ca1f2dff0574b4b3f16a2c7acba47995e7f0fc66b13711f95367d5c0e0db19'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Déjelo como su última opción.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'b23d0995359707965e9b28e1a9d6e01c979764a74d868e003b3cd396e4959200'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profesor y profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-02-12T00:00:00+00:00'::TIMESTAMPTZ, '10f1d045b0f783c78541443014e104093cb0371e68889357a64c47a95096c671'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Aveces le daba muchas vueltas a las explicaciones, quices duros y aunque le puso no me quiso ayudar!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '3f1be14af8624367aa228d74069594fdf1474102e84490457860d06657a2a436'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, '¡Una teja completa! No es el más fácil de los profes, pero cuando acabas el curso puedes estar seguro que has aprendido mucho...y no sólo de Química. Es motivador y te ayuda cuando lo necesitas y mereces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'e155893423a5f60df8c117854d3ad21372aea347a43317df9a112d54e3f4924c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No entiendo la puntuación tan baja. Explica muy bien, es buena gente, hace quices duros pero que ayudan al examen. Muchos ejercicios que se parecen al examen. Excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '35e9d9ebeeac27fa61b8032a029c1a849c88ec56186fce008a7454ce3784aad9'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No me parece que sea el mejor explicando aunque sabe mucho!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4fbf33b247e85668223cee2ff3a21dc15b9d84c93e6a810df0384035e63b9eec'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es duro, reclamos solo bien fundamentados, estudie en casa y estudie mucho por su cuenta.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, '5800fa7e528c75ace1bf697e3538bee2865c259d429cff5d92f8c302d9d7fdf8'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No me quizo ayudar con 2 puntitos. Muchos temas no los entendí, tuve que buscar ayuda.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'd798c609dede4d223773b4a057b554e0ee2fb3baf85a7c800f8a93cee01b4a3e'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '57ecae22ba520ae04de4267486515a5fe7a21025884d87efc0442f63338fea92'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No es la mejor opción si te cuesta química.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '9fafec049db40c0feef6463ea7d8134acf5f595931d35b540e4cdd30df177b7a'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No explica del todo bien, hace demasiado quices'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'ad81cf490b45eee86b6fe6ed535070f3e37fa3dad2e55ec3f6e3c4150e717325'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Sabe mucho y por eso como que se pierde en tanto que dice.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, '857d7f7d28d7513f3c3c67e06307153dc8cb996cd425fd2b8fe0d4d41dda304c'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (547::BIGINT, 'Se le entiede por ratos, se pierde mucho en un tema por hablar de otras cosas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, '802c194de941bcba7657c7d459cda14373e4c3a309ec0a766cac95b3c097ebc8'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, 'Nunca le entendí la verdad jaja pero si sos mujer te ayuda un poco!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-20T00:00:00+00:00'::TIMESTAMPTZ, '13ae73fb6d517a4767e7e930e4ce063403d267c10c5966da93bd749294d27f3b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No explica muy bien, se desvía mucho de la explicación en clases!'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '184566fca8f7cdc4d64526637cdb5dc74461904be5408710519fbf60d2d9501c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Buena gente pero malo explicando, no ayuda.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, '51cb629d35294250140ba3d7436938faf0196b2c8cd1f1e8727eb12acd4dea1b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es toda! Pura vida, explica súper bien, hace ejercicios y además comenta cosas interesantes (no solo de química). Hace quices cada semana lo cual ayuda bastante. Muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '49659d2600d454145870317c0830efa4213354150141ab51955e6acd2bdd65a2'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Sabe demasiado y no es arrogante. Lo prepara súper bien a uno para el examen. Se interesa por sus estudiantes y hace las clases super entretenidas y que valen la pena'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-23T00:00:00+00:00'::TIMESTAMPTZ, '246e8090051200fb96dc19c192b9135325da39d685be586084338dd1cef57e75'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es la neta patineta, al final de semestre te lleva por unas frías. Salu2'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-10-18T00:00:00+00:00'::TIMESTAMPTZ, '1ff2302b64d5bb8f41f43e283cdb7b01116849b6b3330ff23858492bc342c0b4'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (547::BIGINT, 'Hace muchos quices a nivel de examen, da quices extra para los que participan, las "tareas morales" siempre salen en los quices. Prepara súper bien para el examen. Ayuda mucho y explica muy claro. Es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-02T00:00:00+00:00'::TIMESTAMPTZ, '17ee9fbfb62483ef83db36664f503f847cdfce09ad6e7146a21e381c23a4a064'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'muy buen profe matricule sin miedo con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '5266fcccb9ecb3a5ea097a965e312e340dfb8782d470df967eb0aa7fad157e01'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El mejor profesor que he tenido de química, es súper preparado pero nada prepotente y con una habilidad increíble para dar clases, dan ganas de ir'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c06585f13bbae8a2a9bcd15e2106bbe8f23ee606d8bc403a18a01b30ab4a11c9'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Probablemente el mejor profesor de la escuela de química. Se nota que le pone amor a su clase y disfruta la química, y quiere compartir eso con sus estudiantes. Nunca esperé que las clases de química fueran tan interesantes. Lleve con él sin duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '160c3a4e03a5f73b3aed1397e33f5f5d2a1d6934b0d5042d53da5343aa2d2797'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente como profesor y como persona, es increible como amplia los temas en areas que uno no se puede imaginar. Las clases terminan siendo interensantisimas y de gran ayuda. No le gusta dar clases muy largas asi que en un aproximado de una hora o un poco más prepara una clase que vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a7c2af8b32d98f18aba48855c015779b80ba1fdab75660f7492dbb96aa7303db'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Hace las clases muy interactivas y explica muy bien. Super recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '3a56deff057dc2cb8ac953840eab25ba603a6af55d9bcf4b95c56a4579fdcf64'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es súper pura vid. Los quices es solo de repasar un toque la materia y ya los saca. La clase es muy interactivo y explica las cosas muy bien. Hace ejercicios muuuuy similares a los del examen días previos al examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '4bb12b6bd6f49d8a32583cf1009a12dceb7d468427a1b57199165415492b7449'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'El profe es increíblemente divertido pero mas allá de eso es muy atento y se toma el tiempo para que uno entienda en en caso de que tenga una duda. Recomendado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-08T00:00:00+00:00'::TIMESTAMPTZ, '8a4831936892c3a6d0dae097512e2e8847e96e1bd70536c4b6d67c7215898d59'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es muy amigable, con poner atencion en clase esta listo para un examen,no hace clases aburridas, SUPER RECOMENDADO'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2017-03-16T00:00:00+00:00'::TIMESTAMPTZ, '0df5bb215e128311ed1dab8354cc65102388706b06043efc40b7605f447778e6'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Suele desviarse del tema y hacer quices difíciles pero explica muy bien, es pura vida y hace muchos ejercicios similares a los exámenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e04b4fea162635dcf617f6e8aa55f638696d4e1953b34fc5fdd9fb28427159ca'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Es buena persona, pura vida. Como profesor se nota que sabe mucho, explica bien pero a veces no cubre ciertos detalles importantes para el examen. Hace muchos quices sorpresa duros, para los que es importante estudiar. Hay que ponerle bastante, su clase suele pasarla la mitad del grupo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '92e40b68df7af79bd6d54ef5f202c61630ad1804b4734d97f4b20fc13106901c'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'No lo recomiendo para nada, los ejercicios que hace en clase y quices (que ya son muy difíciles) son muy diferentes a los del examen. Solo la minoría logra pasar.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '828d31af0953f613f636ed596800dcecff2e71de599b8d6ca07ec49828e7e59b'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Explica demasiado bien, y con métodos sencillos. Los quices son un poco difíciles por eso hay que estudiar bastante. Explica un poco rápido pero explica las veces que sea necesario para que el estudiante entienda. Ademas es demasiado pura vida y sus historias son excelentes.Se aprende mucho'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '9284ecede97c7457d0d8d16b49570b244c31500e2f5f3fbe34066afbb60a09f1'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Prepara muy bien para los exámenes, se desvía mucho del tema, a veces, pero si explica cosillas extra sobre química, muy interesantes...los quices si son bastante duros'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b23bd7a22edcb0686046f3625c025a07116d0364ed2d26f61523585b393e50e8'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe, muchos quices. Las clases son cortas pero completas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '489d914f5b310f9d5f197b9f390d0cddcd1389c4c5ea614257d024b8661b6b09'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2016-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'e19b35e86e8e2100db12b26a249c52f6aa73997e6ae62b3e159b0457ce7d9da2'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Excelente profe, se interesa por que los estudiantes aprendan. Califica suave y es muy muy pura vida. Las clases son toda, se aprende mucho mas que quimica'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '3dba620c1ee32de04306af3a44cb6ab87501e7674d5a4a8a00f5e875327f4fac'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '27561e2d1c0e06aeffa153aa82e860ae8e395a09ea556194b7dfdbb33c403daf'::TEXT, ARRAY[614]::BIGINT[]),
    (547::BIGINT, 'Muy bueno. Es super pura vida, sus clases son divertidisimas, hace quices todas las semanas MUY parecidos a los examenes y antes de cada examen hace un resumen muy util de toda la materia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '78f33eaac7bb00c41507cd8c0df30ed5fe9b1150b3a5f36072d5cb5e065e7775'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, 'Es súper bueno, muy gracioso y hace las clases cortas. Hace muchos quices'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ee8a705796566e62aba466ae832b1c1cb27863c62d3498dd542a654dd3f5f6bf'::TEXT, ARRAY[568]::BIGINT[]),
    (547::BIGINT, 'Exelente profe, sabe demasiado y transmite su conocimiento bien a los estudiantes. Brinda ejercicios dificiles, parecidos a los exámenes. Sumamente recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-11T00:00:00+00:00'::TIMESTAMPTZ, '115ecae9c81c35502ff6d0e5e139b28069f0deafeedfe88c3190aefb7e38a937'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (547::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2016-06-10T00:00:00+00:00'::TIMESTAMPTZ, '79d5bbacd21daa66c8b752719673b09b40a9e096f7fe7c228a36114b99431d40'::TEXT, ARRAY[614, 568]::BIGINT[]),
    (547::BIGINT, 'Excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-08T00:00:00+00:00'::TIMESTAMPTZ, '494c6a9cb772bcf8657daf65f84bc2af3346ab9a11543d3cb35c7d11cbe6b25d'::TEXT, ARRAY[568]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
